        ("INTERMEDIATE", "class X { public: virtual void go() { std::cout << 'X'; } }; class Y : public X { public: void go() { std::cout << 'Y'; } }; void run(X &r) { r.go(); } Y y; run(y); What is printed?", ["X", "XY", "Compile error", "Y"], "D", "run receives a reference to X, but virtual dispatch uses the dynamic type Y, so Y::go prints Y."),
        ("INTERMEDIATE", "Which statement is true about abstract classes in C++?", ["They can always be instantiated", "They cannot have derived classes", "They cannot declare constructors", "They may have concrete member functions even though they cannot be instantiated"], "D", "Abstract classes can define ordinary member functions and constructors, but cannot be instantiated themselves."),
        ("ADVANCED", "class Base { public: virtual void f() { } ~Base() { std::cout << 'B'; } }; class Derived : public Base { public: int *buf = new int[10]; ~Derived() { delete[] buf; std::cout << 'D'; } }; int main() { Base *p = new Derived; delete p; } Why does this code leak memory?", ["delete is never called", "The Derived destructor never runs, so buf is never freed", "The program crashes at startup", "new int[10] always fails"], "B", "Since ~Base is not virtual, delete p invokes only the base destructor, so Derived's cleanup never runs and buf leaks."),
