        ("BEGINNER", "Which iterator category does a std::vector provide?", ["Bidirectional", "Forward", "Output", "Random access"], "D", "vector iterators support random access, so you can jump to any position in constant time."),
        ("BEGINNER", "Which STL algorithm sorts a range given two iterators?", ["std::reverse", "std::find", "std::sort", "std::count"], "C", "std::sort(first, last) arranges the elements between the two iterators into ascending order."),
        ("BEGINNER", "What is a template in C++?", ["A blueprint that lets functions and classes operate with generic types", "A file that stores compiled code", "A special kind of macro", "A runtime type checker"], "A", "Templates allow writing generic code that the compiler instantiates for specific types."),
        ("BEGINNER", "Which keyword introduces a function template?", ["typename only", "template", "generic", "typeof"], "B", "A function template is introduced with the template keyword, followed by template parameters."),
        ("BEGINNER", "Which container stores unique elements in a sorted order?", ["std::vector", "std::deque", "std::set", "std::stack"], "C", "std::set keeps unique elements sorted, typically implemented as a balanced binary search tree."),
        ("BEGINNER", "Which of the following correctly declares a vector of integers?", ["int vector v;", "vector int v;", "v<int> vector;", "std::vector<int> v;"], "D", "std::vector<int> v; declares an empty vector of ints with the correct template syntax."),
        ("INTERMEDIATE", "std::vector<int> v; for (int i = 0; i < 5; ++i) v.push_back(i * i); std::cout << v[3]; What is the output?", ["3", "6", "9", "16"], "C", "The loop stores the squares 0, 1, 4, 9, 16, and v[3] is the fourth element, which is 9."),
        ("INTERMEDIATE", "std::vector<int> v = { 3, 1, 4, 1, 5 }; std::sort(v.begin(), v.end()); std::cout << v.back(); What is the output?", ["1", "3", "4", "5"], "D", "sort arranges the values in ascending order, so the last element is the maximum, which is 5."),
        ("INTERMEDIATE", "template <typename T> T max_of(T a, T b) { return a > b ? a : b; } std::cout << max_of(3, 7); What is the output?", ["3", "7", "10", "Compile error"], "B", "T is deduced as int, and 7 is greater than 3, so the function returns 7."),
        ("INTERMEDIATE", "std::map<char, int> m; m['a'] = 1; m['b'] = 2; std::cout << m['b']; What is the output?", ["2", "1", "a", "b"], "A", "m['b'] retrieves the value associated with the key 'b', which is 2."),
        ("INTERMEDIATE", "std::vector<int> v = { 10, 20, 30 }; auto it = v.begin(); ++it; std::cout << *it; What is the output?", ["10", "20", "30", "Undefined"], "B", "v.begin() points at 10, and ++it advances to the second element, which is 20."),
        ("INTERMEDIATE", "std::vector<int> v = { 1, 2, 3 }; v.erase(v.begin()); std::cout << v.front(); What is the output?", ["1", "3", "2", "0"], "C", "erase(v.begin()) removes the first element, leaving {2, 3}, so front() is 2."),
        ("INTERMEDIATE", "template <typename T> T square(T x) { return x * x; } std::cout << square(5); What is the output?", ["25", "10", "5", "Compile error"], "A", "T is deduced as int and 5 * 5 equals 25."),
        ("INTERMEDIATE", "Which iterator category does std::sort require to work correctly?", ["Bidirectional", "Random access", "Input", "Output"], "B", "std::sort requires random access iterators, which std::vector and std::deque provide."),
        ("INTERMEDIATE", "std::vector<int> v = { 5, 2, 8 }; std::cout << v.size(); What is the output?", ["5", "2", "8", "3"], "D", "size() returns the number of elements, and the initializer list contains three values."),
        ("INTERMEDIATE", "template <class T> class Box { public: T value; Box(T v) : value(v) {} }; Box<int> b(42); std::cout << b.value; What is the output?", ["0", "Garbage", "Compile error", "42"], "D", "Box<int> instantiates the template with T set to int, so b.value is 42."),
        ("ADVANCED", "template <typename T> void print(T) { std::cout << 'A'; } void print(int) { std::cout << 'B'; } print(5); What is printed?", ["A", "B", "AB", "Compile error"], "B", "A non-template overload is preferred over the template when an exact match exists, so print(int) prints B."),
        ("ADVANCED", "template <typename T> void f(T x) { std::cout << 'T'; } void f(double d) { std::cout << 'D'; } f(3.14); What is printed?", ["T", "DT", "D", "Compile error"], "C", "Passing a double exactly matches the non-template overload f(double), so it prints D."),
        ("ADVANCED", "std::vector<int> v = { 1, 2, 3, 4 }; for (int &x : v) x *= 2; std::cout << v[1]; What is the output?", ["2", "3", "4", "6"], "C", "The range-based loop doubles every element in place through the reference, so v[1] becomes 4."),
        ("ADVANCED", "What is a key reason std::sort with a function object is usually faster than std::qsort with a function pointer?", ["std::sort can inline the comparator because the function object's type is known at compile time", "std::qsort always crashes", "std::sort uses bubble sort", "std::qsort is recursive"], "A", "Templates let std::sort inline the comparison, avoiding the indirect call overhead required by function pointers."),
        ("ADVANCED", "std::vector<int> v; v.reserve(100); v.push_back(1); std::cout << v.size(); Which statement is true about the vector?", ["size is 100 because reserve created elements", "capacity is 100 and size is 1", "capacity is 1 because push_back shrank it", "reserve throws an exception"], "B", "reserve only sets the capacity, so the size stays 1 and the capacity is at least 100."),
        ("ADVANCED", "template <typename T> T sum(T a, T b) { return a + b; } std::cout << sum(2.5, 1.5); What is the output?", ["3", "4.0", "4", "2.5"], "B", "T is deduced as double, so 2.5 + 1.5 equals 4.0."),
        ("ADVANCED", "Which statement best explains why std::vector reallocates when it is full?", ["It shifts existing elements one by one", "It never grows once created", "It allocates a larger buffer, transfers elements, and frees the old buffer", "It uses a linked list internally"], "C", "When full, vector allocates new storage, moves the elements over, and deallocates the old buffer, which invalidates iterators."),
        ("ADVANCED", "What is a lambda expression in C++?", ["An unnamed function object that can capture variables from its enclosing scope", "A macro that expands to a class", "A preprocessor directive", "A virtual function"], "A", "A lambda defines an anonymous callable object that can capture variables from its scope by value or by reference."),
        ("ADVANCED", "template <typename T> void f(T a, T b) { } f(1, 2.5); Why does this fail to compile?", ["Because arguments must be constants", "Because f is not declared", "Because doubles cannot be passed", "Because T cannot be deduced consistently from int and double"], "D", "Both parameters use the same template parameter T, and int conflicts with double, so deduction fails."),
        ("ADVANCED", "Which STL container is the best default choice for most sequences needing random access and efficient growth at the back?", ["std::vector", "std::list", "std::set", "std::forward_list"], "A", "std::vector offers constant-time indexing and amortized constant-time push_back, making it the recommended default sequence container."),
