        ("BEGINNER", "What is the correct signature for overloading + for a class Vec?", ["void operator+(Vec)", "operator Vec +()", "int operator+()", "Vec Vec::operator+(const Vec &other) const"], "D", "An overloaded + returns a new Vec and takes a const reference to the other operand: Vec Vec::operator+(const Vec &other) const."),
        ("BEGINNER", "Which operator inserts data into an output stream such as std::cout?", ["operator>>", "operator<<", "operator+", "operator="], "C", "operator<< is the insertion operator, which sends data to an output stream."),
