        ("INTERMEDIATE", "class Vec { public: int x; Vec operator+(const Vec &o) const { return Vec{x + o.x}; } }; Vec a{3}; Vec b{4}; Vec c = a + b; std::cout << c.x; What is printed?", ["3", "4", "7", "12"], "C", "operator+ adds the x members, so c.x is 3 + 4 = 7."),
        ("INTERMEDIATE", "What happens if you try to read from a file that does not exist using an ifstream?", ["The program crashes", "It creates the file", "The stream stays in a good state", "The stream fails and any read operations will fail"], "D", "Opening a nonexistent file puts the stream in a failed state, so subsequent reads fail and should be checked with fail() or good()."),
        ("INTERMEDIATE", "std::ofstream out('log.txt'); out << 'Hello'; out.close(); What does close() do?", ["Nothing in C++", "Flushes buffered data and releases the file handle", "Deletes the file", "Reopens the file"], "B", "close() flushes the buffer and detaches the stream from the file so other programs can use it."),
        ("INTERMEDIATE", "class Num { public: int v; Num(int x) : v(x) {} bool operator<(const Num &o) const { return v < o.v; } }; Num a(5), b(9); std::cout << (a < b); What is printed?", ["1", "0", "5", "9"], "A", "a < b invokes operator<, which compares 5 < 9 as true and prints it as 1."),
        ("INTERMEDIATE", "Which operator function is called by the expression obj++ for a postfix increment?", ["operator++(obj)", "obj.operator++(int)", "obj.operator++()", "operator++()"], "B", "The postfix operator++ is distinguished by an unused int parameter, so obj++ calls obj.operator++(int)."),
        ("INTERMEDIATE", "std::ifstream in('data.txt'); int x; in >> x; Why might you check in.fail() after extraction?", ["fail() returns the last value read", "fail() is never needed", "fail() indicates the extraction did not succeed, such as at end-of-file or with bad data", "fail() closes the file"], "C", "The extraction operator sets failbit when no valid value could be read, and fail() reports that condition."),
